import React, { useEffect } from "react";
import { useState } from "react";
import { Player } from "video-react";
import MailchimpSubscribe from "react-mailchimp-subscribe";

import splashImage from "../../media/banner.png";
import profilePic from "../../media/Sid_Thakur.jpg";
import introVideo from "../../media/intro_video_480p.mp4";
import "../../../node_modules/video-react/dist/video-react.css";
import Topic from "./Topic";

const Content = (props) => {
  const [heroData, setHeroData] = useState();
  const [workshopData, setWorkshopData] = useState();
  const [aboutData, setAboutData] = useState();

  const CustomForm = ({ status, message, onValidated }) => {
    let email, phone;
    const submit = () =>
      email &&
      email.value.indexOf("@") > -1 &&
      onValidated({
        EMAIL: email.value,
        PHONE: phone.value,
        tags: "4339278",
      });

    return (
      <div
        style={{
          borderRadius: 5,
          padding: 0,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {status === null ? (
          <div
            style={{
              borderRadius: 5,
              display: "flex",
              flexDirection: "column",
              flexWrap: "wrap",
            }}
          >
            <div>
              <input
                style={{
                  borderRadius: 5,
                  flex: 1,
                  fontSize: "1em",
                  marginRight: 10,
                  padding: 5,
                  margin: 5,
                }}
                ref={(node) => (email = node)}
                type="email"
                placeholder="Your email"
              />
              <input
                style={{
                  borderRadius: 5,
                  flex: 1,
                  fontSize: "1em",
                  marginRight: 10,
                  padding: 5,
                  margin: 5,
                  size: 25,
                }}
                ref={(node) => (phone = node)}
                type="phone"
                placeholder="Your phone"
              />
              <button
                style={{
                  borderRadius: 5,
                  fontSize: "1em",
                  padding: 5,
                  margin: 5,
                }}
                onClick={submit}
              >
                Submit
              </button>
            </div>
            {/* <div
              style={{
                display: "flex",
                alignItems: "center",
              }}
            >
              The information you provide will be kept private and will not
              shared.
            </div> */}
          </div>
        ) : (
          <div style={{ color: "white", paddingLeft: 5 }}>
            {status === "sending" && <div>Sending...</div>}
            {status === "error" && (
              <div dangerouslySetInnerHTML={{ __html: message }} />
            )}
            {status === "success" && (
              <div
                dangerouslySetInnerHTML={{
                  __html: "Thank you for signing up! ",
                }}
              />
            )}
          </div>
        )}
      </div>
    );
  };

  useEffect(() => {
    setHeroData(props.data.hero);
    setWorkshopData(props.data.workshop);
    setAboutData(props.data.about);
  });
  return (
    <div className="content">
      <div className="container">
        <div className="row">
          <div className="col-lg-6">
            <div className="hero">
              <h1>{heroData ? heroData.title : "Loading"}</h1>
              <hr />
              <h3>{heroData ? heroData.subTitle : "Loading"}</h3>
              <br />
              <a href="#contact" className="btn btn-custom btn-lg page-scroll">
                Enroll Your Young Innovators
              </a>
            </div>
          </div>
          <div className="col-lg-6">
            <div className="banner">
              <img src={splashImage} className="responsive-image" />
            </div>
          </div>
        </div>
        <div>
          <a id="topics"> </a>
        </div>
        <div className="row">
          <div className="row-separator"></div>
        </div>

        <div className="row">
          <div className="col-lg-12">
            <div className="container section">
              <div className="row">
                <div className="col-lg-12 section-title">
                  <h1>{workshopData ? workshopData.title : "Loading"}</h1>
                </div>
              </div>

              <div className="row">
                <div className="col-lg-8 center-image">
                  <Player playsInline src={introVideo} width={600} />
                </div>
                <div className="col-lg-4 section-subtitle">
                  <h3>{workshopData ? workshopData.subTitle : "Loading"}</h3>
                  <div className="topics">
                    {workshopData && workshopData.topics
                      ? workshopData.topics.map((d, i) => (
                          <Topic key={i} data={d} />
                        ))
                      : ""}
                  </div>
                </div>
              </div>
              {/* <div className="row">
                <div className="col-lg-12">
                  <a
                    href="#topics"
                    className="btn btn-custom btn-lg"
                  >
                    Learn More
                  </a>
                </div>
              </div> */}
            </div>
          </div>
        </div>
        <div>
          <a id="about"> </a>
        </div>

        <div className="row">
          <div className="row-separator"></div>
        </div>
        <div className="row">
          <div className="col-lg-12">
            <div className="container section-no-bg">
              <div className="row">
                <div className="col-lg-12 section-title">
                  {<h1>{aboutData ? aboutData.title : "Loading"}</h1>}
                </div>
              </div>

              <div className="row">
                <div className="col-lg-4 order-2 center-image">
                  <img
                    src={profilePic}
                    className="responsive-image profile-pic"
                  />
                </div>{" "}
                <div className="col-lg-5 order-1">
                  <p>
                    {aboutData ? aboutData.subTitle : "Loading"}{" "}
                    {aboutData ? (
                      <a href={aboutData.link.url} target="_window">{aboutData.link.title} </a>
                    ) : (
                      ""
                    )}
                  </p>
                </div>
                <div className="col-lg-1"> </div>
              </div>
            </div>
          </div>
        </div>

        <div>
          <a id="contact"> </a>
        </div>
        <div className="row">
          <div className="row-separator"></div>
        </div>
        <div className="row">
          <div className="col-lg-12">
            <div className="container section">
              <div className="row">
                <div className="col-lg-12 section-title">
                  {<h1>{"Contact"}</h1>}
                </div>
              </div>

              <div className="row">
                <div className="col-lg-6">
                  <div
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      alignItems: "center",
                    }}
                  >
                    <span
                      style={{
                        fontSize: "1.1rem",
                        fontWeight: "600",
                        paddingLeft: 10,
                        padding: 10,
                      }}
                    >
                      Sign up to receive updates <i class="icon-rocket "></i>
                    </span>
                    <MailchimpSubscribe
                      url={process.env.REACT_APP_MAILCHIMP_KEY}
                      render={({ subscribe, status, message }) => (
                        <CustomForm
                          status={status}
                          message={message}
                          onValidated={(formData) => subscribe(formData)}
                        />
                      )}
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="row">
          <div className="row-separator"></div>
        </div>
      </div>
    </div>
  );
};

export default Content;
